interface Org {
  id: string;
  name?: string;
  [key: string]: unknown;
}

interface User {
  id: string;
  orgId: string;
  org?: Org;
  [key: string]: unknown;
}

async function loadUser(id: string): Promise<User> {
  const userRes = await fetch(`/api/users/${encodeURIComponent(id)}`);
  if (!userRes.ok) {
    throw new Error(`Failed to load user ${id}: HTTP ${userRes.status}`);
  }

  const user = (await userRes.json()) as User;

  const orgRes = await fetch(`/api/orgs/${encodeURIComponent(user.orgId)}`);
  if (!orgRes.ok) {
    throw new Error(`Failed to load org ${user.orgId}: HTTP ${orgRes.status}`);
  }

  const org = (await orgRes.json()) as Org;

  return { ...user, org };
}

async function loadUsers(ids: readonly string[]): Promise<User[]> {
  return Promise.all(ids.map((id) => loadUser(id)));
}

export { loadUser, loadUsers };

